-- AuthKit 2.4.0 (rp_id: 2.6.0): passkey table auth_kit_webauthn_credential, MariaDB 10.5+ (binary NO PAD collation utf8mb4_nopad_bin on the exact-key columns).
-- Generated from the ORM mapping of Nowo\AuthKitBundle\Entity\WebauthnCredential; checked against it in CI.
-- With nowo_auth_kit.doctrine.table_prefix, prefix the table and index names.
CREATE TABLE auth_kit_webauthn_credential (id INT AUTO_INCREMENT NOT NULL, public_id VARCHAR(32) CHARACTER SET utf8mb4 NOT NULL COLLATE `utf8mb4_nopad_bin`, profile VARCHAR(64) NOT NULL, user_type VARCHAR(191) CHARACTER SET utf8mb4 NOT NULL COLLATE `utf8mb4_nopad_bin`, user_id VARCHAR(191) CHARACTER SET utf8mb4 NOT NULL COLLATE `utf8mb4_nopad_bin`, credential_id_hash VARCHAR(64) CHARACTER SET utf8mb4 NOT NULL COLLATE `utf8mb4_nopad_bin`, credential_id LONGTEXT NOT NULL, user_handle VARCHAR(64) CHARACTER SET utf8mb4 NOT NULL COLLATE `utf8mb4_nopad_bin`, public_key LONGTEXT NOT NULL, sign_count BIGINT NOT NULL, transports JSON NOT NULL, aaguid VARCHAR(36) DEFAULT NULL, backup_eligible TINYINT DEFAULT NULL, backup_state TINYINT DEFAULT NULL, label VARCHAR(100) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME DEFAULT NULL, rp_id VARCHAR(253) DEFAULT NULL, INDEX idx_auth_kit_webauthn_owner (profile, user_type, user_id), UNIQUE INDEX uniq_auth_kit_webauthn_public_id (public_id), UNIQUE INDEX uniq_auth_kit_webauthn_credential (credential_id_hash), PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_unicode_ci`;
